{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C36"],
      "claim": "MK-458, an N-propyl aminotetralin with a phenolic hydroxyl, had absolute oral bioavailability of only about 5% in Parkinson's patients across sustained-release oral doses; this direct low-F measurement weakly transfers to the query's N-propyl, hydroxyl-bearing alkaloid scaffold and supports F < 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "3-PPP, a structurally related N-propyl phenolic aminotetralin, failed in clinical trials due to low oral bioavailability, supporting a low-F outcome for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "A close N-propyl morpholine phenol analogue was predicted to have 0% human oral bioavailability based on animal data, reinforcing the likelihood that the query also has F < 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Levoprotiline, a hydroxylated tricyclic antidepressant, had 40% absolute oral bioavailability in healthy volunteers, providing weak contradictory evidence that some polar hydroxyl-containing analogues can exceed 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a quaternary ammonium alkaloid with multiple hydroxyls; such permanently charged, polar scaffolds typically have poor membrane permeability and low oral bioavailability. The closest experimental analogues with N-propyl and phenolic/amino alcohol features (MK-458, 3-PPP, compound 26) show very low or negligible oral bioavailability. Although some weakly related antidepressants have F > 20%, they lack the quaternary ammonium liability and have low transferability. Therefore F < 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query or a close quaternary ammonium analogue.",
    "Morgan similarities to all evidence molecules are low (~0.18-0.19), limiting transferability.",
    "The ionization state is uncertain because the SMILES contains a formal positive charge while the physicochemical prior reports a high neutral fraction.",
    "No metabolism, transporter, or solubility data are available for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

